import{c as s,a1 as o,U as l,j as i,g as t,o as r,a6 as u,p as c,n as d}from"./chunks/framework.h4W4t1IS.js";const x=JSON.parse('{"title":"Routeur","description":"","frontmatter":{"title":"Routeur","status":"ready","tags":["architecture","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"architecture/routeur.md","filePath":"architecture/routeur.md"}'),p={name:"architecture/routeur.md"},h={id:"frontmatter-title",tabindex:"-1"};function g(a,e,m,v,b,q){const n=o("Icon");return l(),i("div",null,[t("h1",h,[r(u(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1)),e[1]||(e[1]=r()),c(n,{icon:"mdi:bell-circle",style:{color:"var(--vp-c-tip-1)","vertical-align":"-0.1em","margin-left":"0.3em"},"aria-label":"Nouveau contenu"})]),e[2]||(e[2]=d(`<p>Le <strong><a href="/420-w30-sf-po2/lexique.html#routeur" class="lexicon-link" title="Composante qui achemine chaque requête émise par une vue vers le contrôleur approprié, de sorte que la vue n&#39;a pas à connaître le contrôleur.">Routeur</a></strong> achemine chaque action de l&#39;utilisateur vers le contrôleur approprié. C&#39;est grâce à lui que la vue n&#39;a pas besoin de connaître le contrôleur.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Décrire le contenu d&#39;une requête (destination et données)</li><li>Expliquer le rôle du Routeur dans <a href="/420-w30-sf-po2/lexique.html#mvc" class="lexicon-link" title="Patron architectural en trois couches : le modèle (domaine, ignore tout du reste), la vue (affiche des DTOs, ignore le modèle), le contrôleur (orchestre les deux, connaît modèle ET vue).">MVC</a></li><li>Expliquer comment le Routeur découple la vue du contrôleur</li></ul></div><h2 id="la-requete" tabindex="-1">La requête <a class="header-anchor" href="#la-requete" aria-label="Permalink to &quot;La requête&quot;">​</a></h2><p>Une <strong>requête</strong> est un message composé de deux parties :</p><ul><li>une <strong>destination</strong> : le contrôleur visé ;</li><li>des <strong>données</strong> : ce dont le contrôleur a besoin pour traiter la requête.</li></ul><h2 id="le-role-du-routeur" tabindex="-1">Le rôle du Routeur <a class="header-anchor" href="#le-role-du-routeur" aria-label="Permalink to &quot;Le rôle du Routeur&quot;">​</a></h2><p><strong>Responsabilités :</strong></p><ul><li>Recevoir les requêtes émises par les vues (et par les contrôleurs)</li><li>Trouver le contrôleur correspondant à la destination</li><li>Lui confier l&#39;exécution de la requête</li></ul><p>Toutes les requêtes passent par ce <strong>chemin unique</strong>, ce qui permet de les traiter de façon uniforme (par exemple, gérer les erreurs à un seul endroit).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐   requête    ┌──────────┐   exécute    ┌──────────────┐</span></span>
<span class="line"><span>│   Vue    │ ───────────► │ Routeur  │ ───────────► │  Contrôleur  │</span></span>
<span class="line"><span>└──────────┘              └──────────┘              └──────────────┘</span></span></code></pre></div><h2 id="un-decouplage-delibere" tabindex="-1">Un découplage délibéré <a class="header-anchor" href="#un-decouplage-delibere" aria-label="Permalink to &quot;Un découplage délibéré&quot;">​</a></h2><p>La vue émet des <strong>requêtes</strong>, jamais des appels directs à un contrôleur :</p><ul><li>la vue ignore <strong>qui</strong> la servira ;</li><li>le contrôleur ignore <strong>qui</strong> l&#39;a demandé.</li></ul><p>On peut donc ajouter, remplacer ou réorganiser des contrôleurs sans modifier les vues.</p><h2 id="avantages" tabindex="-1">Avantages <a class="header-anchor" href="#avantages" aria-label="Permalink to &quot;Avantages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avantage</th><th>Description</th></tr></thead><tbody><tr><td><strong>Chemin unique</strong></td><td>Toutes les requêtes de l&#39;application passent par un seul endroit</td></tr><tr><td><strong>Découplage</strong></td><td>La vue et le contrôleur ne se connaissent pas</td></tr><tr><td><strong>Ouvert à l&#39;extension</strong></td><td>Ajouter un contrôleur ne demande aucune modification des vues existantes</td></tr></tbody></table>`,17))])}const _=s(p,[["render",g]]);export{x as __pageData,_ as default};
